-- A sheet is created the first time its id is loaded; everything else is kept per sheet.
CREATE TABLE sheet (
    id VARCHAR(100) PRIMARY KEY
);
-- Each sheet has its own "today": every date-dependent decision and default date uses it, never the
-- real clock. It starts as the real date when the sheet is first loaded.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CURRENT_DATE WHERE today IS NULL;
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
-- People kept on a sheet, listed in the order they were added (id order). grade is one of A, B, C.
CREATE TABLE person (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name VARCHAR(200) NOT NULL,
    grade VARCHAR(1) NOT NULL
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- A person's name is unique on its sheet, ignoring case and surrounding spaces; names are stored trimmed.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(name));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
-- A person's claims: an amount (0.00 or more, two decimals), a date and a note (may be empty).
-- Listed newest first (id order, descending).
CREATE TABLE claim (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    amount DECIMAL(15, 2) NOT NULL,
    claim_date DATE NOT NULL,
    note VARCHAR(1000) NOT NULL DEFAULT ''
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
-- The sheet's rate for each grade: a percent with two decimals. A grade with no row has no rate.
CREATE TABLE rate (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade VARCHAR(10) NOT NULL,
    rate DECIMAL(7, 2) NOT NULL,
    PRIMARY KEY (sheet_id, grade)
);
-- A claim's status: DRAFT -> OPEN -> SETTLED; DRAFT or OPEN -> VOID. SETTLED and VOID are final.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL;
-- An opened claim gets the sheet's next number (1, 2, ...), never reused; a draft has none, and
-- voiding a claim clears it. The sheet keeps the last number it gave out.
ALTER TABLE sheet ADD COLUMN last_claim_number INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN claim_number INT;
-- Settling a claim fixes its due (its amount at its person's grade's rate at that moment), so later
-- rate changes do not alter it. Null while the claim is live: not settled, or settled with no rate.
ALTER TABLE claim ADD COLUMN due DECIMAL(25, 2);
-- A rate may carry a from-date: a grade can have several rates, one per from-date (null = from the
-- beginning of time). A claim uses its grade's rate with the latest from-date on or before its date.
ALTER TABLE rate DROP PRIMARY KEY;
ALTER TABLE rate ADD COLUMN from_date DATE;
CREATE INDEX rate_sheet_grade ON rate (sheet_id, grade, from_date);
-- The user who opened a claim (four eyes: they cannot also settle it). Null until the claim is opened.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(255);
-- Each save of a person bumps its version; an edit names the version it loaded and is refused when
-- someone else has saved the person since.
ALTER TABLE person ADD COLUMN version INT DEFAULT 0 NOT NULL;
-- A person's statement records their due-total at that moment and binds each of their counting
-- claims to the figure it has then. The person keeps how many statements were taken, the last one's
-- due-total ('n/a' when it had none) and the sheet's today when it was taken.
ALTER TABLE person ADD COLUMN statement_count INT DEFAULT 0 NOT NULL;
ALTER TABLE person ADD COLUMN stated_total VARCHAR(30);
ALTER TABLE person ADD COLUMN statement_date DATE;
-- A stated claim shows and totals its bound figure (stated_due; null: n/a) until its person's next
-- statement rebinds it, or unbinds it (live again) when it no longer counts.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(25, 2);
-- A sheet's periods: a name unique on the sheet (ignoring case; stored trimmed) and a from and to
-- date, both inclusive. No two periods on a sheet overlap. A claim belongs to the period whose dates
-- contain its date, or to none.
CREATE TABLE period (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name VARCHAR(100) NOT NULL,
    name_key VARCHAR(100) GENERATED ALWAYS AS (LOWER(name)),
    from_date DATE NOT NULL,
    to_date DATE NOT NULL
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
-- A period can be closed: its due-total is then fixed at closed_total, whatever the rates do later,
-- and no claim dated inside it can be added, edited, opened, settled or voided.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(19, 2);
-- A person can be retired from a date: they count as retired at once, whatever the date, and a claim
-- dated after it is refused. Null while the person is not retired.
ALTER TABLE person ADD COLUMN retired_from DATE;
-- A person can be put on hold: while held, their open claims count in no live total (settled ones still do).
ALTER TABLE person ADD COLUMN held BOOLEAN NOT NULL DEFAULT FALSE;
-- The sheet's clerk limit: a clerk settles a claim only when its due is at or below it; null: no limit.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(15, 2);
-- The role a user name has on a sheet; a name with no row is a clerk.
CREATE TABLE user_role (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    role VARCHAR(20) NOT NULL,
    PRIMARY KEY (sheet_id, user_name)
);
-- The sheet's floor: a claim's live due is at least it.
ALTER TABLE sheet ADD COLUMN due_floor DECIMAL(15, 2) NOT NULL DEFAULT 1.00;
-- The sheet's terms: a claim is due by its date plus this many days.
ALTER TABLE sheet ADD COLUMN terms INT NOT NULL DEFAULT 14;
-- The sheet's late percent: an overdue claim's due gains this percent of its figure for every full 30 days it is overdue.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(15, 2) NOT NULL DEFAULT 0.00;
-- A person's patrons: other people on the same sheet they name, each at most once. A person's backing is
-- their patrons' due-totals added up.
CREATE TABLE person_patron (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    patron_id BIGINT NOT NULL REFERENCES person (id),
    PRIMARY KEY (person_id, patron_id)
);
CREATE INDEX person_patron_sheet ON person_patron (sheet_id);
-- A person's grades, each recorded from a from-date (null = from the beginning of time: the first grade
-- the person was given). The grade in force on a date is the one with the latest from-date on or before
-- it; person.grade keeps only the first grade given.
CREATE TABLE person_grade (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    grade VARCHAR(1) NOT NULL,
    from_date DATE
);
CREATE INDEX person_grade_sheet ON person_grade (sheet_id, person_id);
INSERT INTO person_grade (sheet_id, person_id, grade, from_date) SELECT sheet_id, id, grade, NULL FROM person;
-- A correction (a claim with a negative amount) names, by number, the settled claim of the same person it
-- corrects; null for any other claim.
ALTER TABLE claim ADD COLUMN corrects INT;
-- The sheet's rounding policy date: a claim dated before it rounds half up, one on or after it half to even; null: the sheet's today.
ALTER TABLE sheet ADD COLUMN policy_date DATE;
-- The sheet's period numbering from date: while it is set and the sheet's today is on or after it, an opened
-- claim is numbered within its period (<period name>-<n>; X-<n> for a claim in no period); null: off.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
-- A claim's number (and the number a correction names) is now text: a sheet-wide 1, 2, ... or a per-period P1-1, X-1.
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(120);
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(120);
-- The last number each per-period sequence gave out: seq_key is the period's name in lower case, or '' for
-- the claims in no period (X). A number taken is never given out again.
CREATE TABLE period_claim_number (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    seq_key VARCHAR(100) NOT NULL,
    last_number INT NOT NULL,
    PRIMARY KEY (sheet_id, seq_key)
);
-- Where a claim is listed among its person's: newest (highest) first. A new claim takes the next value; a claim
-- moved to another person takes the next value again, so it is listed as its new person's newest claim.
CREATE SEQUENCE claim_listed_seq START WITH 1;
ALTER TABLE claim ADD COLUMN listed BIGINT DEFAULT NEXT VALUE FOR claim_listed_seq NOT NULL;
CREATE INDEX claim_sheet_listed ON claim (sheet_id, listed);
-- Terms set for a grade: a claim whose person has that grade on its date is due by its date plus them. A grade
-- without its own terms uses the sheet's terms.
CREATE TABLE grade_terms (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade VARCHAR(1) NOT NULL,
    terms INT NOT NULL,
    PRIMARY KEY (sheet_id, grade)
);
-- A claim's due-by, fixed when it is created: its date plus the terms of its person's grade in force on its date.
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim SET due_by = DATEADD(DAY, (SELECT s.terms FROM sheet s WHERE s.id = claim.sheet_id), claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
-- A claim's status log: one line per status it has had, oldest first (id order) — the status, the user who
-- gave it, the sheet's today then, and the claim's due as computed at that moment ('n/a' when it had none).
CREATE TABLE claim_log (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    claim_id BIGINT NOT NULL REFERENCES claim (id),
    status VARCHAR(20) NOT NULL,
    by_user VARCHAR(200) NOT NULL,
    log_date DATE NOT NULL,
    due VARCHAR(30) NOT NULL
);
CREATE INDEX claim_log_sheet ON claim_log (sheet_id, claim_id, id);
-- A person's holds, each from a from-date to an optional to-date (null: no end), both inclusive; a person may
-- have several over time. Only their open claims dated within a hold, and not bound by a statement, are left out
-- of the live totals. A person held before holds had dates is held from the beginning of time (null from-date).
CREATE TABLE person_hold (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE,
    to_date DATE
);
CREATE INDEX person_hold_sheet ON person_hold (sheet_id, person_id);
INSERT INTO person_hold (sheet_id, person_id, from_date, to_date) SELECT sheet_id, id, NULL, NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
-- A rate may carry a to-date (null: no end), inclusive: it applies through that day. A claim dated after the
-- to-date of the rate that would apply to it, with no later rate in force on its date, has no rate (n/a).
ALTER TABLE rate ADD COLUMN to_date DATE;
-- The sheet's cap: a person's due-total is at most it; null: no cap.
ALTER TABLE sheet ADD COLUMN due_cap DECIMAL(15, 2);
-- Each person's due-total for a closed period, fixed when it was closed: the dues of their counting claims dated
-- in it. A person with no row here (added after the close) shows 0.00 for it. Cleared when the period reopens.
CREATE TABLE period_person_total (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    period_name VARCHAR(100) NOT NULL,
    person_id BIGINT NOT NULL,
    total DECIMAL(19, 2) NOT NULL,
    PRIMARY KEY (sheet_id, period_name, person_id)
);
-- A dated setting's values, each in force from its date until the next one's; before every from-date the
-- sheet's starting value (floor 1.00, late percent 0.00, terms 14; none for the clerk limit, the cap and a
-- grade's own terms). setting_value null: blank (no limit, no cap, a grade without its own terms).
CREATE TABLE setting_from (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    setting_key VARCHAR(20) NOT NULL,
    from_date DATE NOT NULL,
    setting_value VARCHAR(30),
    PRIMARY KEY (sheet_id, setting_key, from_date)
);
-- Values already set carry over as in force from the start.
INSERT INTO setting_from (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'floor', DATE '1900-01-01', CAST(due_floor AS VARCHAR(30)) FROM sheet WHERE due_floor <> 1.00;
INSERT INTO setting_from (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'late-pct', DATE '1900-01-01', CAST(late_pct AS VARCHAR(30)) FROM sheet WHERE late_pct <> 0.00;
INSERT INTO setting_from (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'terms', DATE '1900-01-01', CAST(terms AS VARCHAR(30)) FROM sheet WHERE terms <> 14;
INSERT INTO setting_from (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'clerk-limit', DATE '1900-01-01', CAST(clerk_limit AS VARCHAR(30)) FROM sheet WHERE clerk_limit IS NOT NULL;
INSERT INTO setting_from (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'cap', DATE '1900-01-01', CAST(due_cap AS VARCHAR(30)) FROM sheet WHERE due_cap IS NOT NULL;
INSERT INTO setting_from (sheet_id, setting_key, from_date, setting_value)
    SELECT sheet_id, 'terms-' || grade, DATE '1900-01-01', CAST(terms AS VARCHAR(30)) FROM grade_terms;
-- The date an OPEN claim is deferred until (null: not deferred). Until the sheet's today reaches it the claim
-- counts in no total, is not overdue, cannot be settled and is left unbound by a statement.
ALTER TABLE claim ADD COLUMN deferred_until DATE;
-- How many proofs a claim has been given. A claim whose due is above the sheet's proof threshold in force on its date
-- cannot be settled or approved while it has none.
ALTER TABLE claim ADD COLUMN proofs INT NOT NULL DEFAULT 0;
-- The roles allowed an action (open, settle, void, reassign, close, reopen) on a sheet, comma separated; an action
-- with no row keeps the standing rule (open, settle, void and close by clerk and steward; reassign and reopen by steward).
CREATE TABLE permission (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    action VARCHAR(20) NOT NULL,
    roles VARCHAR(100) NOT NULL,
    PRIMARY KEY (sheet_id, action)
);
-- The sheet's grace days: when its today is changed, an open period whose to-date plus them is before the new
-- today is closed; null: off. Not dated.
ALTER TABLE sheet ADD COLUMN grace_days INT;
-- The number of the claim a claim was split from (null: not split off another claim). The claim split keeps
-- none; only the new claim carries it.
ALTER TABLE claim ADD COLUMN split_from VARCHAR(120);
-- Who watches whom: a signed-in user watching a person on the sheet, each at most once. The id keeps the order they
-- started watching; stopping deletes the row, so watching again starts afresh at the end.
CREATE TABLE person_watch (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    user_name VARCHAR(100) NOT NULL,
    UNIQUE (person_id, user_name)
);
CREATE INDEX person_watch_sheet ON person_watch (sheet_id, person_id);
-- The steward role delegated by a steward (by_user) to a user name on a sheet, from a from-date to a to-date, both
-- inclusive: while the sheet's today is inside them the user acts as a steward. The id keeps the order they were made.
CREATE TABLE delegation (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    from_date DATE NOT NULL,
    to_date DATE NOT NULL,
    by_user VARCHAR(100) NOT NULL
);
CREATE INDEX delegation_sheet ON delegation (sheet_id, user_name);
-- A steward can archive a sheet: it stays visible but every change to it is refused.
ALTER TABLE sheet ADD COLUMN archived BOOLEAN DEFAULT FALSE NOT NULL;
-- A person's own terms: a claim of theirs is due by its date plus this many days, before their grade's or the
-- sheet's terms. Null: none of their own.
ALTER TABLE person ADD COLUMN terms INT;
-- A claim whose editor a user has open is locked for every other user until that user saves or cancels the editor,
-- or the sheet's today changes. At most one lock per claim.
CREATE TABLE claim_lock (
    sheet_id VARCHAR(255) NOT NULL,
    claim_id BIGINT NOT NULL,
    locked_by VARCHAR(255) NOT NULL,
    PRIMARY KEY (sheet_id, claim_id)
);
-- A period can be soft-closed: its due-total (closed_total) and each person's figure for it (period_person_total)
-- are fixed then, as for a close, but claims dated inside it can still be added, edited, opened, settled and voided.
ALTER TABLE period ADD COLUMN soft_closed BOOLEAN DEFAULT FALSE NOT NULL;
-- A claim added while the period containing its date was soft-closed is a late entry; it stays one.
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN DEFAULT FALSE NOT NULL;
-- Each statement taken of a person, in order (seq from 1), with its due-total ('n/a' when it had none) and date, so
-- the last one can be cancelled and the person shows the one before it again. A person's last statement before this
-- change is kept as their only known one.
CREATE TABLE person_statement (
    sheet_id VARCHAR(100) NOT NULL,
    person_id BIGINT NOT NULL,
    seq INT NOT NULL,
    stated_total VARCHAR(30),
    statement_date DATE,
    PRIMARY KEY (sheet_id, person_id, seq)
);
INSERT INTO person_statement (sheet_id, person_id, seq, stated_total, statement_date)
    SELECT sheet_id, id, statement_count, stated_total, statement_date FROM person WHERE statement_count > 0;
-- The sheet as it stood each time its today was changed (from_today -> to_today): its people, claims, rates, dated
-- settings and policy date as JSON, so a statement can be taken as of an earlier date. started is the sheet's today
-- when it was first loaded (nothing was on it before).
CREATE TABLE sheet_day (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    from_today DATE NOT NULL,
    to_today DATE NOT NULL,
    state CLOB NOT NULL
);
CREATE INDEX sheet_day_sheet ON sheet_day (sheet_id, id);
ALTER TABLE sheet ADD COLUMN started DATE;
UPDATE sheet SET started = today;
-- The schema holding a copy of every row kept for the sheet as it stood when its today moved on (see AsOfSchemas), so
-- the whole screen can be read as of an earlier date.
ALTER TABLE sheet_day ADD COLUMN snapshot VARCHAR(64);
-- The sheet's entry date: while it is set, it is the date a new claim left without one takes (the claim form, the
-- quick-add bar, a pasted line, a correction) instead of the sheet's today; null: off.
ALTER TABLE sheet ADD COLUMN entry_date DATE;
-- The last sheet-today a reminder was written for the claim (null: never reminded).
ALTER TABLE claim ADD COLUMN reminded_on DATE;
-- A holiday on a sheet: a claim's due-by, fixed when it is created, that would fall on one moves to the next day
-- that is not one. A date is on a sheet's list at most once.
CREATE TABLE holiday (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    holiday_date DATE NOT NULL,
    PRIMARY KEY (sheet_id, holiday_date)
);
-- A claim's external reference (null: none), and the same lower-cased: a reference is used at most once on a sheet,
-- comparing without regard to case.
ALTER TABLE claim ADD COLUMN external_ref VARCHAR(120);
ALTER TABLE claim ADD COLUMN external_ref_key VARCHAR(120);
CREATE UNIQUE INDEX claim_external_ref_key ON claim (sheet_id, external_ref_key);
-- A claim's tags (null: none): lower-cased, sorted and comma separated. Every tag ever given to a claim on a sheet
-- stays on the sheet's tag list, even once no claim carries it.
ALTER TABLE claim ADD COLUMN tags VARCHAR(1000);
CREATE TABLE claim_tag (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    tag VARCHAR(1000) NOT NULL,
    PRIMARY KEY (sheet_id, tag)
);
-- The sheet's void reasons, in the order they were added: a reason is on a sheet's list at most once. While the list
-- is not empty, a claim is voided with a reason chosen from it, kept on the claim (null: voided with none).
CREATE TABLE void_reason (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    reason VARCHAR(200) NOT NULL,
    position INT NOT NULL,
    PRIMARY KEY (sheet_id, reason)
);
ALTER TABLE claim ADD COLUMN void_reason VARCHAR(200);
-- A claim's comments, oldest first (id order): the text, the user who wrote it and the sheet's today then.
CREATE TABLE claim_comment (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    claim_id BIGINT NOT NULL REFERENCES claim (id),
    by_user VARCHAR(200) NOT NULL,
    comment_date DATE NOT NULL,
    text VARCHAR(4000) NOT NULL
);
CREATE INDEX claim_comment_sheet ON claim_comment (sheet_id, claim_id, id);
-- The user who last edited a claim through its editor or its row's amount entry (four eyes: they cannot settle or
-- approve it). Null until the claim is first edited.
ALTER TABLE claim ADD COLUMN edited_by VARCHAR(255);
-- A bulk settle that settles at least one claim (one going PENDING counts) is a batch, numbered 1, 2, ... on the
-- sheet in the order the batches happen: last_batch is the sheet's last batch number (0: none yet). Each settle of a
-- bulk settle carries the bulk settle's token; the first claim it settles takes the batch number for that token.
-- A claim keeps the number of the batch that settled it (null: settled one at a time, or never settled).
ALTER TABLE sheet ADD COLUMN last_batch INT NOT NULL DEFAULT 0;
CREATE TABLE settle_batch (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    token VARCHAR(100) NOT NULL,
    number INT NOT NULL,
    PRIMARY KEY (sheet_id, token)
);
ALTER TABLE claim ADD COLUMN batch INT;
-- A person's contact, kept trimmed and lower-cased; null: none. No two people on a sheet share one.
ALTER TABLE person ADD COLUMN contact VARCHAR(200);
-- A person's aliases, kept trimmed. Aliases share the names' uniqueness: no alias equals, ignoring case, another
-- alias or any person's name on the sheet.
CREATE TABLE person_alias (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    alias VARCHAR(200) NOT NULL,
    alias_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(alias))
);
CREATE UNIQUE INDEX person_alias_sheet_key ON person_alias (sheet_id, alias_key);
-- The sheet's claim templates: a name (trimmed, unique on the sheet), an amount (0.00 or more, two decimals) and a
-- note (may be empty). Saving a name again replaces its template; a claim made from one copies its amount and note.
CREATE TABLE claim_template (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name VARCHAR(200) NOT NULL,
    amount DECIMAL(15, 2) NOT NULL,
    note VARCHAR(1000) NOT NULL DEFAULT '',
    PRIMARY KEY (sheet_id, name)
);
-- The sheet's pools: a name (trimmed, unique on the sheet), listed in the order they were added (id order).
CREATE TABLE pool (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name VARCHAR(200) NOT NULL,
    UNIQUE (sheet_id, name)
);
-- A pool's members: a person (at most once per pool, in any number of pools) with a share percent (more than 0.00,
-- at most 100.00), listed in the order they were added (id order).
CREATE TABLE pool_member (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    pool_id BIGINT NOT NULL REFERENCES pool (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    share DECIMAL(5, 2) NOT NULL,
    UNIQUE (pool_id, person_id)
);
-- The sheet's pot: shared out among the members of each balanced pool by their shares; null: none. Not dated.
ALTER TABLE sheet ADD COLUMN pot DECIMAL(15, 2);
-- The order a person named their patrons in (seq order): 100.00 is split equally among a person's patrons, each share
-- rounded half to even to two decimals, the remainder going to the first named. Existing patrons keep their old
-- (patron id) order.
ALTER TABLE person_patron ADD COLUMN seq BIGINT AUTO_INCREMENT;
-- The sheet's parent sheet: a grade with no rate in force on a date here takes the parent's (then its parent's, up to
-- three levels up); null: none. Not dated.
ALTER TABLE sheet ADD COLUMN parent_id VARCHAR(100);

