cat > $A/RowCopy.java <<'EOF'
package net.officefloor.hq.app;

import java.sql.PreparedStatement;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;

/** Copies a stored row to a new row of the same table, every column it was given kept, under a new id. */
public final class RowCopy {

    private RowCopy() {
    }

    /** Copy the row with this id of the table (its id the identity column {@code id}); the new row's id. */
    public static long copy(JdbcTemplate jdbc, String table, long id) {
        List<String> columns = jdbc.queryForList("SELECT column_name FROM information_schema.columns WHERE"
                + " table_schema = 'PUBLIC' AND table_name = ? AND is_identity = 'NO' AND is_generated = 'NEVER'"
                + " ORDER BY ordinal_position", String.class, table.toUpperCase());
        String list = String.join(", ", columns);
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement("INSERT INTO " + table + " (" + list + ") SELECT " + list
                    + " FROM " + table + " WHERE id = ?", new String[] { "id" });
            ps.setLong(1, id);
            return ps;
        }, keys);
        return keys.getKey().longValue();
    }
}
